// bae-anim-samples.jsx - build keyframe/expression test cases in After Effects and record
// AE's own evaluated values, as reference data for bae-anim (workstream 03).
//
// Formats: docs/interop/ae-anim-samples.md. Input: samples/anim-cases.json (generated by
// samples/gen_anim_cases.py). Output: a bae-anim-samples JSON file.
// Runs in After Effects CC 2018 (15.0) and later; needs bae-export.jsx in the same folder.
//
// Interactive: File > Scripts > Run Script File..., pick the cases file, then the output file.
// Headless: define BAE_ANIM_SAMPLES_OPTIONS = {casesPath: "...", outputPath: "...", keepComps: false}
// before evaluating this file. Tests define BAE_ANIM_SAMPLES_NO_AUTORUN = true.

(function (global) {
    var here = new File($.fileName).parent;
    if (typeof BAE_EXPORT === "undefined" || !BAE_EXPORT) {
        global.BAE_EXPORT_NO_AUTORUN = true;
        $.evalFile(here.fsName + "/bae-export.jsx");
    }
    var B = BAE_EXPORT;
    var S = {};
    S.VERSION = "0.1.0";
    var FLICKS_PER_SECOND = 705600000;

    function hasOwn(obj, key) {
        return Object.prototype.hasOwnProperty.call(obj, key);
    }

    function isArray(v) {
        return Object.prototype.toString.call(v) === "[object Array]";
    }

    function seconds(flicks) {
        return Number(flicks) / FLICKS_PER_SECOND;
    }

    function merge(a, b) {
        var out = {};
        var k;
        for (k in a || {}) {
            if (hasOwn(a, k)) {
                out[k] = a[k];
            }
        }
        for (k in b || {}) {
            if (hasOwn(b, k)) {
                out[k] = b[k];
            }
        }
        return out;
    }

    // ------------------------------------------------------------------ Value / AttrSpec -> AE

    var INTERP = {linear: "LINEAR", bezier: "BEZIER", hold: "HOLD"};

    function interpType(token) {
        var name = INTERP[token || "linear"];
        if (!name) {
            throw new Error("unknown interpolation " + token);
        }
        return KeyframeInterpolationType[name];
    }

    /** Fit a numeric array to the property's current dimension count (2D layers report 2 or 3). */
    function fitLength(arr, len) {
        var out = [];
        for (var i = 0; i < len; i++) {
            out.push(i < arr.length ? arr[i] : 0);
        }
        return out;
    }

    /** bae-model Value JSON -> raw AE value for `prop`. */
    S.aeValue = function (v, prop) {
        if (v.type === "float" || v.type === "int") {
            return v.value;
        }
        if (v.type === "bool") {
            return v.value ? 1 : 0;
        }
        if (v.type === "vec2" || v.type === "vec3" || v.type === "color") {
            var cur = prop.value;
            return isArray(cur) ? fitLength(v.value, cur.length) : v.value[0];
        }
        throw new Error("value type " + v.type + " is not supported by the sample builder");
    };

    function easeList(list, count) {
        var out = [];
        for (var i = 0; i < count; i++) {
            var e = list[Math.min(i, list.length - 1)];
            out.push(new KeyframeEase(e.speed, e.influence));
        }
        return out;
    }

    /** Number of KeyframeEase entries AE expects for this property (scripting guide). */
    function easeCount(prop) {
        var vt = prop.propertyValueType;
        if (vt === PropertyValueType.TwoD) {
            return 2;
        }
        if (vt === PropertyValueType.ThreeD) {
            return 3;
        }
        return 1;
    }

    /**
     * Apply a bae-model AttrSpec (keyframes keyed by flicks in comp time, docs 4.2) to an AE
     * property. Order matters: AE recomputes auto-Bezier eases and roving times when flags change,
     * so values and interpolation go first, eases and tangents next, flags last.
     */
    S.applyAttr = function (prop, spec) {
        while (prop.numKeys > 0) {
            prop.removeKey(1);
        }
        if (prop.canSetExpression) {
            prop.expression = "";
        }
        var times = [];
        var t;
        for (t in spec.keyframes || {}) {
            if (hasOwn(spec.keyframes, t)) {
                times.push(t);
            }
        }
        times.sort(function (a, b) {
            return Number(a) - Number(b);
        });
        if (times.length === 0 && spec.value) {
            prop.setValue(S.aeValue(spec.value, prop));
        }
        var indices = [];
        var i;
        var kf;
        for (i = 0; i < times.length; i++) {
            kf = spec.keyframes[times[i]];
            prop.setValueAtTime(seconds(times[i]), S.aeValue(kf.value, prop));
        }
        for (i = 0; i < times.length; i++) {
            indices.push(prop.nearestKeyIndex(seconds(times[i])));
        }
        var spatial = prop.isSpatial;
        var dims = isArray(prop.value) ? prop.value.length : 1;
        for (i = 0; i < times.length; i++) {
            kf = spec.keyframes[times[i]];
            var k = indices[i];
            prop.setInterpolationTypeAtKey(k, interpType(kf.interp_in), interpType(kf.interp_out));
            if (kf.ease_in || kf.ease_out) {
                var n = easeCount(prop);
                var ein = kf.ease_in || kf.ease_out;
                var eout = kf.ease_out || kf.ease_in;
                prop.setTemporalEaseAtKey(k, easeList(ein, n), easeList(eout, n));
            }
            if (spatial && (kf.spatial_in || kf.spatial_out)) {
                prop.setSpatialTangentsAtKey(k, fitLength(kf.spatial_in || [0, 0, 0], dims),
                    fitLength(kf.spatial_out || [0, 0, 0], dims));
            }
        }
        for (i = 0; i < times.length; i++) {
            kf = spec.keyframes[times[i]];
            var f = kf.flags || {};
            var key = indices[i];
            prop.setTemporalContinuousAtKey(key, !!f.temporal_continuous);
            prop.setTemporalAutoBezierAtKey(key, !!f.temporal_auto_bezier);
            if (spatial) {
                prop.setSpatialContinuousAtKey(key, !!f.spatial_continuous);
                prop.setSpatialAutoBezierAtKey(key, !!f.spatial_auto_bezier);
            }
            if (kf.label) {
                try {
                    prop.setLabelAtKey(key, kf.label);
                } catch (e) {
                    // keyframe labels need AE 22.6+
                }
            }
        }
        // Roving last: AE retimes roving keys only once their neighbours are final.
        if (spatial) {
            for (i = 0; i < times.length; i++) {
                kf = spec.keyframes[times[i]];
                if (kf.flags && kf.flags.roving) {
                    prop.setRovingAtKey(indices[i], true);
                }
            }
        }
        if (spec.expression) {
            prop.expression = spec.expression.source;
            prop.expressionEnabled = spec.expression.enabled !== false;
        }
    };

    // ------------------------------------------------------------------ cases

    function findProperty(layer, path) {
        var p = layer;
        for (var i = 0; i < path.length; i++) {
            var next = p.property(path[i]);
            if (!next) {
                throw new Error("property not found: " + path.slice(0, i + 1).join(" / "));
            }
            p = next;
        }
        return p;
    }

    function makeLayer(comp, spec) {
        var layer;
        var type = spec.type || "null";
        if (type === "null") {
            layer = comp.layers.addNull();
        } else if (type === "solid") {
            layer = comp.layers.addSolid([0.5, 0.5, 0.5], "solid", comp.width, comp.height, comp.pixelAspect);
        } else if (type === "shape") {
            layer = comp.layers.addShape();
        } else {
            throw new Error("unknown layer type " + type);
        }
        layer.name = spec.name || "case";
        if (spec.three_d) {
            layer.threeDLayer = true;
        }
        var effects = spec.effects || [];
        for (var i = 0; i < effects.length; i++) {
            layer.property("ADBE Effect Parade").addProperty(effects[i]);
        }
        if (spec.separate_position) {
            layer.property("ADBE Transform Group").property("ADBE Position").dimensionsSeparated = true;
        }
        if (spec.start_time !== undefined) {
            layer.startTime = seconds(spec.start_time);
        }
        if (spec.stretch !== undefined) {
            layer.stretch = spec.stretch;
        }
        return layer;
    }

    function rawToArray(raw) {
        if (isArray(raw)) {
            var out = [];
            for (var i = 0; i < raw.length; i++) {
                out.push(isFinite(raw[i]) ? raw[i] : null);
            }
            return out;
        }
        return [isFinite(raw) ? raw : null];
    }

    var VALUE_TYPE = {};

    function valueTypeName(vt) {
        if (!VALUE_TYPE.done) {
            var names = ["OneD", "TwoD", "TwoD_SPATIAL", "ThreeD", "ThreeD_SPATIAL", "COLOR"];
            var tokens = ["float", "vec2", "vec2", "vec3", "vec3", "color"];
            for (var i = 0; i < names.length; i++) {
                VALUE_TYPE["$" + PropertyValueType[names[i]]] = tokens[i];
            }
            VALUE_TYPE.done = true;
        }
        return VALUE_TYPE["$" + vt] || "unsupported";
    }

    /** Sample times in flicks: from..to (inclusive) in steps of frame/per_frame. */
    function sampleTimes(sample, frameFlicks) {
        var step = frameFlicks / sample.per_frame;
        var from = Number(sample.from);
        var to = Number(sample.to);
        var out = [];
        for (var k = 0; ; k++) {
            var t = Math.round(from + k * step);
            if (t > to) {
                break;
            }
            out.push(t);
        }
        return out;
    }

    function frameFlicksOf(fps) {
        // Rational rates from the cases file keep NTSC frames exact; fall back to the float rate.
        if (fps.num && fps.den) {
            return FLICKS_PER_SECOND * fps.den / fps.num;
        }
        return FLICKS_PER_SECOND / fps;
    }

    S.runCase = function (c, defaults, folder) {
        var compSpec = merge(defaults.comp, c.comp);
        var fr = compSpec.frame_rate;
        var fps = fr.num ? fr.num / fr.den : fr;
        var comp = app.project.items.addComp("bae_" + c.id, compSpec.width, compSpec.height, 1,
            seconds(compSpec.duration), fps);
        if (folder) {
            comp.parentFolder = folder;
        }
        var result = {id: c.id};
        try {
            var layer = makeLayer(comp, merge(merge(defaults.layer, c.layer), {name: c.id}));
            var others = c.other || [];
            for (var o = 0; o < others.length; o++) {
                S.applyAttr(findProperty(layer, others[o].property), others[o].attr);
            }
            var prop = findProperty(layer, c.property);
            S.applyAttr(prop, c.attr);
            var readBack = B.propertyAttrSpec(prop);
            result.comp = {width: comp.width, height: comp.height, frame_rate: comp.frameRate,
                duration: B.toFlicks(comp.duration)};
            result.layer = {start_time: B.toFlicks(layer.startTime), stretch: layer.stretch,
                in_point: B.toFlicks(layer.inPoint), out_point: B.toFlicks(layer.outPoint),
                three_d: !!layer.threeDLayer};
            result.property = {path: c.property, value_type: valueTypeName(prop.propertyValueType),
                spatial: !!prop.isSpatial, dimensions: rawToArray(prop.value).length};
            result.attr = readBack.spec || {};
            var times = sampleTimes(merge(defaults.sample, c.sample), frameFlicksOf(fr));
            var pre = [];
            var post = [];
            var hasExpr = !!(c.attr.expression && c.attr.expression.source);
            for (var i = 0; i < times.length; i++) {
                pre.push(rawToArray(prop.valueAtTime(seconds(times[i]), true)));
                if (hasExpr) {
                    post.push(rawToArray(prop.valueAtTime(seconds(times[i]), false)));
                }
            }
            result.times = times;
            result.pre_expression = pre;
            if (hasExpr) {
                result.post_expression = post;
                if (prop.expressionError) {
                    result.expression_error = String(prop.expressionError);
                }
            }
            var notes = readBack.warnings.concat(readBack.unsupported);
            if (notes.length) {
                result.notes = notes;
            }
        } catch (e) {
            result.error = String(e) + (e.line ? " (line " + e.line + ")" : "");
        }
        return {result: result, comp: comp};
    };

    S.run = function (options) {
        var casesFile = new File(options.casesPath);
        casesFile.encoding = "UTF-8";
        if (!casesFile.open("r")) {
            throw new Error("cannot read " + casesFile.fsName);
        }
        var cases = B.parseJSON(casesFile.read());
        casesFile.close();
        if (cases.format !== "bae-anim-cases") {
            throw new Error(casesFile.fsName + " is not a bae-anim-cases file");
        }
        app.beginUndoGroup("BAE anim samples");
        var folder = app.project.items.addFolder("BAE anim samples");
        var results = [];
        var failed = 0;
        try {
            for (var i = 0; i < cases.cases.length; i++) {
                var only = options.only;
                if (only && only !== cases.cases[i].id) {
                    continue;
                }
                var r = S.runCase(cases.cases[i], cases.defaults || {}, folder);
                results.push(r.result);
                if (r.result.error) {
                    failed++;
                }
                if (!options.keepComps) {
                    r.comp.remove();
                }
            }
        } finally {
            if (!options.keepComps) {
                folder.remove();
            }
            app.endUndoGroup();
        }
        var doc = {
            format: "bae-anim-samples",
            format_version: S.VERSION,
            generator: {name: "bae-anim-samples", version: S.VERSION},
            host: {app: "After Effects", version: String(app.version), build: String(app.buildName),
                os: String($.os), expression_engine: String(app.project.expressionEngine)},
            exported_at: "",
            cases_format_version: cases.format_version,
            time: {unit: "flicks", flicks_per_second: FLICKS_PER_SECOND, key_time_base: "comp"},
            results: results
        };
        var d = new Date();
        doc.exported_at = d.getUTCFullYear() + "-" + pad2(d.getUTCMonth() + 1) + "-" + pad2(d.getUTCDate()) + "T" +
            pad2(d.getUTCHours()) + ":" + pad2(d.getUTCMinutes()) + ":" + pad2(d.getUTCSeconds()) + "Z";
        var out = new File(options.outputPath);
        out.encoding = "UTF-8";
        out.lineFeed = "Unix";
        if (!out.open("w")) {
            throw new Error("cannot write " + out.fsName);
        }
        out.write(B.stringify(doc, ""));
        out.write("\n");
        out.close();
        return {doc: doc, failed: failed};
    };

    function pad2(n) {
        return n < 10 ? "0" + n : String(n);
    }

    function main() {
        var headless = typeof BAE_ANIM_SAMPLES_OPTIONS !== "undefined" && BAE_ANIM_SAMPLES_OPTIONS;
        global.BAE_ANIM_SAMPLES_OPTIONS = undefined;
        var options = headless;
        if (!options) {
            var cases = new File(here.fsName + "/samples/anim-cases.json").openDlg("anim-cases.json", "*.json");
            if (!cases) {
                return;
            }
            var out = new File(cases.parent.fsName + "/anim-samples.ae.json").saveDlg("bae-anim-samples", "*.json");
            if (!out) {
                return;
            }
            options = {casesPath: cases.fsName, outputPath: out.fsName};
        }
        var msg;
        try {
            var r = S.run(options);
            msg = r.doc.results.length + " cases, " + r.failed + " failed -> " + options.outputPath;
        } catch (e) {
            msg = "bae-anim-samples failed: " + e + (e.line ? " (line " + e.line + ")" : "");
        }
        if (headless) {
            $.writeln(msg);
        } else {
            alert(msg);
        }
    }

    global.BAE_ANIM_SAMPLES = S;
    var noAutorun = typeof BAE_ANIM_SAMPLES_NO_AUTORUN !== "undefined" && BAE_ANIM_SAMPLES_NO_AUTORUN;
    global.BAE_ANIM_SAMPLES_NO_AUTORUN = undefined;
    if (!noAutorun) {
        main();
    }
}(this));
